node -e "
const db = require('better-sqlite3')('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));
for (const t of tables) {
  const info = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  console.log('\n' + t.name + ' columns:', info.map(c => c.name));
}
"

node -e "
const db = require('better-sqlite3')('/workspace/world.db');
const user = db.prepare(\"SELECT * FROM users WHERE user_id = ?\").get('user_d3d5d0c8');
if (user) {
  for (const [k, v] of Object.entries(user)) {
    if (k.endsWith('_json') && v) {
      console.log(k + ':', JSON.stringify(JSON.parse(v), null, 2));
    } else {
      console.log(k + ':', v);
    }
  }
} else {
  console.log('User not found');
}
"

