node -e "
const db = require('better-sqlite3')('/workspace/world.db');
// Search for wireless mice, excluding the original product
const mice = db.prepare(\"SELECT product_id, name, brand, category, subcategory, price, current_price, in_stock, stock_quantity, rating, review_count, description, specs_json FROM products WHERE (LOWER(name) LIKE '%mouse%' OR LOWER(subcategory) LIKE '%mouse%') AND LOWER(name) LIKE '%wireless%' AND product_id != 'PROD-FA0948'\").all();
if (mice.length === 0) {
  // broader search
  const broader = db.prepare(\"SELECT product_id, name, brand, category, subcategory, price, current_price, in_stock, stock_quantity, rating, review_count, description FROM products WHERE LOWER(name) LIKE '%mouse%' AND product_id != 'PROD-FA0948'\").all();
  console.log('Broader search (all mice):');
  broader.forEach(m => console.log(JSON.stringify(m, null, 2)));
} else {
  mice.forEach(m => console.log(JSON.stringify(m, null, 2)));
}
"

